INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will US withdraw from NATO before 2027?', 'This market will resolve to "Yes" if the United States formally initiates a withdrawal from NATO or provides an official notice of denunciation to NATO by December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to "No".

A notice of denunciation refers to the submission of a notice of withdrawal as per Article 13 of the North Atlantic Treaty.

Any action meeting these criteria will qualify for a “Yes” resolution regardless of if its implementation is immediately halted or delayed by judicial or other actions.

The U.S.''s exit from NATO’s integrated military command structure will not be sufficient to resolve this market to "Yes". 

The resolution source will be official information from the US government and NATO, however a consensus of credible reporting may also be used.', 'politics', 'active', 21234.32, 622230.06, 21734.32, 622730.06);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Minnesota Vikings win the 2027 NFL NFC Championship?', 'This market will resolve according to the team that wins the 2027 NFC championship game.

If at any point it becomes impossible for a listed team to win the 2027 NFL NFC championship per the rules of the NFL (e.g., they are eliminated in the playoffs), the corresponding market will resolve to “No”.

If the 2027 NFL NFC championship game is cancelled, postponed after March 31, 2027 ET, or there is otherwise no winner declared within that timeframe, this market will resolve to “Other”.

The primary resolution source will be official information from NFL (https://www.nfl.com/); however, a consensus of credible reporting may also be used.', 'sports', 'active', 35096.36, 913453.9, 35596.36, 913953.9);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Grigor Dimitrov win the 2026 Men''s US Open?', 'The 2026 U.S. Open tennis tournament is scheduled for August 23 - September 13, 2026.

This market will resolve to the player that wins the 2026 U.S. Open Men’s Singles Tournament.

If at any point it becomes impossible for a listed player to win the 2026 U.S. Open Men’s Singles Tournament per the rules of the tournament, the corresponding market will resolve to “No”.

If the 2026 U.S. Open Men’s Singles Tournament is cancelled, postponed after October 31, 2026, or there is otherwise no winner declared within that timeframe, this market will resolve to “Other”.

The primary resolution source will be official information from the U.S. Open (https://www.usopen.org/index.html); however, a consensus of credible reporting may also be used.', 'sports', 'active', 3769.02, 373132.88, 4269.02, 373632.88);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Predict.fun FDV above $200M one day after launch?', 'This market will resolve to "Yes" if the Fully Diluted Valuation of Predict.fun''s governance token is greater than the value specified in the title 1 day after launch. Otherwise, the market will resolve to "No."

The token must be actively, publicly transferable and tradable to be considered a launch.

The FDV will be determined using the total token supply multiplied by the token price.

"1 day after launch" is defined as 4:00 PM ET on the calendar day following launch. The resolution source for this market is the most liquid price source available. If Predict.fun (https://predict.fun/) doesn''t launch a token by December 31, 2027, 11:59 PM ET, this market will resolve to "No".', 'crypto', 'active', 409890.18, 140297.98, 410390.18, 140797.98);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Russia test a nuclear weapon by September 30 2026?', 'This market will resolve to "Yes" if Russia conducts a nuclear test by the listed date (ET). Otherwise, this market will resolve to "No".

A nuclear test is defined as the intentional non-combat detonation of a device by Russia that produces a nuclear chain reaction (fission or fusion), regardless of yield.

Accidents, radiological dispersal devices (bombs that spread radioactive material using conventional explosives such as "dirty bombs"), or actions by third parties will not count toward this market''s resolution.

Tests not explicitly claimed by Russia may still qualify if a clear consensus of credible reporting attributes the nuclear detonation to Russia. For example, an unclaimed nuclear test analogous to the 1979 "Vela Incident" would count if credible reporting attributes it to Russia.

The resolution source for this market will be a broad consensus of credible reporting.', 'politics', 'active', 941.43, 68793.82, 1441.4299999999998, 69293.82);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Russia x Ukraine ceasefire agreement by December 31, 2026?', 'This market will resolve to “Yes” if there is a ceasefire agreement between Russia and Ukraine by the specified date, 11:59 PM ET. Otherwise, this market will resolve to “No”.

A ceasefire agreement refers to any mutually-agreed suspension of direct military engagement between Russia and Ukraine, which is either officially announced by both countries or confirmed by a consensus of credible reporting to have been mutually agreed by both countries.

A broader peace deal, normalization agreement, political framework, truce, or humanitarian pause will qualify if it includes a mutually agreed suspension of direct military engagement, to be effective on a specified date. Agreements that outline future negotiations or de-escalation measures without an explicit, dated commitment to stop fighting will not qualify.

Any form of informal understanding, backchannel communication, de-escalation without an announced agreement, or unilateral pause in hostilities will not be considered a ceasefire agreement.

Only agreements which constitute a general pause in the conflict will qualify. Agreements which only apply to specific conflict categories (e.g. restrictions on certain target categories or certain locations) will not qualify.

If a qualifying agreement is officially reached before this market’s end date, this market will resolve to “Yes,” regardless of whether the ceasefire agreement officially takes effect after that date.

The primary resolution sources for this market will be official information from the governments of Russia and Ukraine and a consensus of credible reporting.', 'politics', 'active', 281128.35, 779733.34, 281628.35, 780233.34);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will NVIDIA be the largest company in the world by market cap on December 31?', 'This market will resolve to the largest company in the world by market cap on December 31, 2026, as of market close.

The resolution source for this market will be a consensus of credible reporting.', 'tech', 'active', 356469.71, 149161.09, 356969.71, 149661.09);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will WTI Crude Oil (WTI) hit (HIGH) $85 in August?', 'This market will resolve to "Yes" if, at any point after market creation and during a trading session of August 2026, any 1-minute candle for the Active Month of WTI Crude Oil futures has a final "High" or "Low" price equal to or beyond (above for ↑ High Prices, below for ↓ Low Prices) the listed price. Otherwise, this market will resolve to "No".

Prices will be used exactly as published by Pyth, without rounding.

If the Active Month contract does not trade at all during the listed time frame, this market will resolve to "No".

Only prices achieved during an applicable trading session of the specified timeframe''s business days will be considered. The trading session for a given business day typically begins at 6:00 PM ET on the prior calendar date. Under the standard schedule, trading is open from 6:00:00 PM ET Sunday through 5:00:00 PM ET Friday, with a daily break from 5:00:00 PM ET to 6:00:00 PM ET, except where modified by holiday or special-session hours.

The active month changes at the start of the second trading session prior to the nearest listed contract''s last trading session. At that point, the next listed contract becomes the active month (i.e., for the final three trading sessions of the nearest listed contract, the contract for the next month is the active month).

Per CME contract specifications for WTI Crude Oil (CL) futures, a contract''s last trading day is three business days prior to the 25th calendar day of the month preceding the contract''s delivery month (or four business days prior if the 25th calendar day is not a business day).

For example, if the 25th of the month is a Saturday, the last trading session for the nearest listed contract is the session for Tuesday the 21st, and the next listed contract becomes the active month at the start of the trading session for Friday the 17th (6:00 PM ET on Thursday), assuming a standard trading calendar.

If the relevant Pyth data is unavailable due to a system outage, data failure, or other technical disruption that prevents verification of the required 1-minute candle data, the official daily high/low price published for the Active Month WTI Crude Oil (CL) futures contract by CME Group may be used to determine whether the listed price was reached during the applicable trading session.

In the event of a contract specification change, feed change, or similar structural modification affecting the underlying market during the listed time frame, this market will resolve based on adjusted prices as displayed on Pyth.

The resolution source for this market is Pyth — specifically, the Active Month WTI Crude Oil futures "High" and "Low" prices available at https://pythdata.app/explore?search=WTI, with the chart settings configured for 1-minute candles. Historical 1-minute candles may be accessed by appending a Unix timestamp (seconds) to the Pyth chart URL using the "t=" parameter.', 'general', 'active', 222173.37, 60850.03, 222673.37, 61350.03);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Puffpaw FDV above $100M one day after launch?', 'This market will resolve to "Yes" if the Fully Diluted Valuation of Puffpaw''s governance token is greater than the value specified in the title 1 day after launch. Otherwise, the market will resolve to "No."

The token must be actively, publicly transferable and tradable to be considered a launch.

The FDV will be determined using the total token supply multiplied by the token price.

"1 day after launch" is defined as 4:00 PM ET on the calendar day following launch. The resolution source for this market is the most liquid price source available. If Puffpaw (https://www.puffpaw.xyz/) doesn''t launch a token by December 31, 2026, 11:59 PM ET, this market will resolve to "No".', 'crypto', 'active', 169105.25, 676421.02, 169605.25, 676921.02);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Russia invade a NATO country by December 31, 2026?', 'This market will resolve to "Yes" if Russia commences a military offensive intended to establish control over any portion of any NATO country by December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to "No".

For the purposes of this market, land de facto controlled by NATO member states or Russia as of May 28, 2025, will be considered the sovereign territory of those countries.

Hybrid or “grey zone” operations conducted by unmarked personnel will qualify if they are confirmed to be Russian operatives and are intended to establish de facto control over territory, as occurred in Crimea (2014) or Donbas (2014–2022).

The resolution source for this market will be a consensus of credible sources.', 'politics', 'active', 6834.78, 117433.87, 7334.78, 117933.87);